  const mottZone = T => (j, i) => { const r = T.rpm[i]; if (r <= T.aMax) return 'A'; const c = T.cFrom.find(e => T.teeth[j] <= e[0]); return (c && r >= c[1]) ? 'C' : 'B'; };
  const s20Zone = no => i => { const r = S20.rpm[i], z = S20.zone[no]; return r <= z[0] ? 'A' : r <= z[1] ? 'B' : r <= z[2] ? 'C' : 'C′'; };
