    if (!T) return { why: 'not in Mott (40/60/80 only)' };
    const zo = src === 'renold' ? ((j, i) => T.z[j][i]) : mottZone(T);
    const r = gridAt(T, zo, N, n), r17 = gridAt(T, zo, 17, n);
    if (!r) return { why: (N < T.teeth[0] || N > T.teeth[T.teeth.length - 1]) ? 'teeth outside ' + T.teeth[0] + '–' + T.teeth[T.teeth.length - 1] : 'beyond the table (not rated)' };
    return { hp: r.hp, h17: r17 ? r17.hp : undefined, k1: r17 ? r.hp / r17.hp : undefined, z: r.z };
